-- ============================================================
-- nielcos.ai customs: HTS schedule backfill (PART 12/12)
-- Source: USITC HTS 2026 Rev 19 official JSON.
-- 8-digit lines stored as 10-digit ".00" records in the official JSON;
-- skipped by the PART 1-4 import. Same guarded upsert as parts 1-4.
-- Run parts 5-16 in order, once, in the Supabase SQL editor.
-- ============================================================



on conflict (hts_no) do update set description=excluded.description, general_rate=excluded.general_rate, unit=excluded.unit, rate_text=excluded.rate_text, revision=excluded.revision;
